# stress test. Tenere allineato con frontend/src/navRoutes.ts quando si aggiunge una schermata.
# Campi: route (deep link reale; "" = nessuna pagina), title, path (percorso di navigazione), body (cosa fa + come si usa),
# kw (parole chiave extra per la ricerca), roles (vuoto = tutti; superadmin/master/manager/collab).
