MASTER = "Pannello Master"
PUB = "Pagine pubbliche"
ECO = "Ecosistema AdvisorOS"  # V50.z563 — domini/sottopagine del VPS (voci solo Super Master)


def _a(route: str, title: str, path: str, body: str, kw: str = "", roles: str = "", how: str = "") -> Dict:
    # V50.z561 — `how` (come si usa) esplicito; se vuoto il backend separa le frasi operative dalla descrizione (axon_manual._mn_split_how).
    return {"route": route, "title": title, "path": path, "body": body, "kw": kw, "roles": [r for r in roles.split() if r], "how": how}


