    _a("/libretto-editor", "Editor Libretto", f"{ADM} → Libretto → Modifica", "Modifica i testi del Libretto.", "editor libretto", "superadmin"),
    _a("/faq", "FAQ", f"{TAB} → Aiuto → FAQ", "Domande frequenti con ricerca semantica (digita e compaiono i suggerimenti), filtrate per ruolo.", "faq domande"),
    _a("/help-center", "Help Center", f"{TAB} → Aiuto → Help Center", "FAQ, Manuale completo con ricerca full-text, apertura ticket di supporto.", "help center ticket supporto"),
    _a("/help-center-admin", "Help Center admin", f"{ADM} → Help Center admin", "Gestione ticket e FAQ.", "ticket admin", "superadmin master"),
