    _a("/admin/org-plans", "Piani Org (posti team)", f"{MASTER} → Piani Org", "Collaboratore 19€, Master10 50€, Master50 100€, Enterprise: posti massimi per tenant.", "piani org posti", "superadmin master"),
    _a("/admin/beta", "Beta tester", f"{MASTER} → Beta", "Gestione beta tester e feedback.", "beta", "superadmin"),
    _a("/admin/customers", "Clienti (admin)", f"{MASTER} → Clienti", "Elenco tenant/clienti paganti.", "tenant clienti", "superadmin"),
    _a("/admin/onboarding", "Onboarding (admin)", f"{MASTER} → Onboarding", "Stato onboarding degli utenti.", "onboarding admin", "superadmin"),
    _a("/admin/promo-codes", "Codici promo", f"{MASTER} → Codici promo", "Crea e gestisci codici sconto/Founder.", "promo codici sconto", "superadmin"),
    _a("/admin/register-guard", "Register guard", f"{MASTER} → Register guard", "Protezione registrazioni (whitelist, limiti).", "registrazioni protezione", "superadmin"),
